class Solution {
  public int eraseOverlapIntervals(int[][] intervals) {
    Arrays.sort(intervals, (a, b) -> Integer.compare(a[1], b[1]));
    int removals = 0;
    int lastEnd = Integer.MIN_VALUE;
    for (int[] interval : intervals) {
      if (interval[0] >= lastEnd) lastEnd = interval[1];
      else removals++;
    }
    return removals;
  }
}

class Solution {
  public int hIndex(int[] citations) {
    int n = citations.length;
    int[] buckets = new int[n + 1];
    for (int citation : citations) buckets[Math.min(citation, n)]++;
    int papers = 0;
    for (int h = n; h >= 0; h--) {
      papers += buckets[h];
      if (papers >= h) return h;
    }
    return 0;
  }
}

class Solution {
  public void wiggleSort(int[] nums) {
    for (int i = 1; i < nums.length; i++) {
      boolean shouldRise = i % 2 == 1;
      if (shouldRise && nums[i] < nums[i - 1]) swap(nums, i, i - 1);
      if (!shouldRise && nums[i] > nums[i - 1]) swap(nums, i, i - 1);
    }
  }

  private void swap(int[] nums, int i, int j) {
    int temp = nums[i];
    nums[i] = nums[j];
    nums[j] = temp;
  }
}

class Solution {
  public void wiggleSort(int[] nums) {
    int median = select(nums.clone(), nums.length / 2);
    int left = 0;
    int index = 0;
    int right = nums.length - 1;
    while (index <= right) {
      int mapped = map(index, nums.length);
      if (nums[mapped] > median) {
        swap(nums, map(left++, nums.length), mapped);
        index++;
      } else if (nums[mapped] < median) {
        swap(nums, mapped, map(right--, nums.length));
      } else {
        index++;
      }
    }
  }

  private int select(int[] nums, int target) {
    int left = 0, right = nums.length - 1;
    while (left <= right) {
      int pivot = partition(nums, left, right);
      if (pivot == target) return nums[pivot];
      if (pivot < target) left = pivot + 1;
      else right = pivot - 1;
    }
    return nums[target];
  }

  private int partition(int[] nums, int left, int right) {
    int pivot = nums[right];
    int store = left;
    for (int i = left; i < right; i++) if (nums[i] <= pivot) swap(nums, store++, i);
    swap(nums, store, right);
    return store;
  }

  private int map(int index, int n) {
    return (1 + 2 * index) % (n | 1);
  }

  private void swap(int[] nums, int i, int j) {
    int temp = nums[i];
    nums[i] = nums[j];
    nums[j] = temp;
  }
}

class ListNode {
  int val;
  ListNode next;
  ListNode() {}
  ListNode(int val) { this.val = val; }
  ListNode(int val, ListNode next) { this.val = val; this.next = next; }
}

class Solution {
  public ListNode sortList(ListNode head) {
    int length = 0;
    for (ListNode node = head; node != null; node = node.next) length++;
    ListNode dummy = new ListNode(0, head);
    for (int size = 1; size < length; size *= 2) {
      ListNode current = dummy.next;
      ListNode tail = dummy;
      while (current != null) {
        ListNode left = current;
        ListNode right = split(left, size);
        current = split(right, size);
        tail = merge(left, right, tail);
      }
    }
    return dummy.next;
  }

  private ListNode split(ListNode head, int size) {
    for (int i = 1; head != null && i < size; i++) head = head.next;
    if (head == null) return null;
    ListNode second = head.next;
    head.next = null;
    return second;
  }

  private ListNode merge(ListNode a, ListNode b, ListNode tail) {
    while (a != null && b != null) {
      if (a.val <= b.val) {
        tail.next = a;
        a = a.next;
      } else {
        tail.next = b;
        b = b.next;
      }
      tail = tail.next;
    }
    tail.next = (a != null) ? a : b;
    while (tail.next != null) tail = tail.next;
    return tail;
  }
}

