class Solution {
  public List<Integer> countSmaller(int[] nums) {
    int[] sorted = nums.clone();
    Arrays.sort(sorted);
    Map<Integer, Integer> rank = new HashMap<>();
    int id = 1;
    for (int value : sorted) if (!rank.containsKey(value)) rank.put(value, id++);
    int[] tree = new int[id + 1];
    Integer[] answer = new Integer[nums.length];
    for (int i = nums.length - 1; i >= 0; i--) {
      int r = rank.get(nums[i]);
      answer[i] = query(tree, r - 1);
      update(tree, r, 1);
    }
    return Arrays.asList(answer);
  }

  private void update(int[] tree, int index, int delta) {
    while (index < tree.length) {
      tree[index] += delta;
      index += index & -index;
    }
  }

  private int query(int[] tree, int index) {
    int sum = 0;
    while (index > 0) {
      sum += tree[index];
      index -= index & -index;
    }
    return sum;
  }
}

