class Solution {
  public int reversePairs(int[] nums) {
    TreeSet<Long> values = new TreeSet<>();
    for (int value : nums) {
      values.add((long) value);
      values.add(2L * value);
    }
    Map<Long, Integer> rank = new HashMap<>();
    int id = 1;
    for (long value : values) rank.put(value, id++);
    int[] tree = new int[id + 1];
    int pairs = 0;
    for (int i = 0; i < nums.length; i++) {
      int lessOrEqualDouble = query(tree, rank.get(2L * nums[i]));
      pairs += i - lessOrEqualDouble;
      update(tree, rank.get((long) nums[i]), 1);
    }
    return pairs;
  }

  private void update(int[] tree, int index, int delta) {
    while (index < tree.length) {
      tree[index] += delta;
      index += index & -index;
    }
  }

  private int query(int[] tree, int index) {
    int sum = 0;
    while (index > 0) {
      sum += tree[index];
      index -= index & -index;
    }
    return sum;
  }
}

